contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint _am, uint _lockTime, uint _minSum) public payable {
        require(address(this).balance >= _am, "insufficient test balance");

        uint balBefore = address(c).balance;

        c.Put{value: _am}(_lockTime);

        uint accBefore = c.Acc(address(this)).balance;

        bool reverted;
        try c.Collect(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint accAfter = c.Acc(address(this)).balance;
        uint balAfter = address(c).balance;

        if (reverted) {
            assert(accAfter == accBefore);
            assert(balAfter == balBefore);
        } else {
            assert(accAfter == accBefore - _am);
            assert(balAfter == balBefore - _am);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
