    }

    function run(uint _am, uint _minSum) public payable {
        require(address(this).balance >= _am, "insufficient test balance");
        require(_am > 0, "amount must be positive");

        // fund the caller's account inside c and make it collectable
        c.SetMinSum(_minSum);
        c.Put{value: _am}(0);

        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;

        bool reverted;
        try c.Collect(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;

        if (reverted) {
            assert(afterBal == beforeBal);
            assert(cBalAfter == cBalBefore);
        } else {
            assert(afterBal == beforeBal - _am);
            assert(cBalAfter == cBalBefore - _am);
        }
    }

    receive() external payable {}
}

