    constructor(C _c) {
        c = _c;
    }

    function run(uint _am, uint _deposit) public payable {
        require(_deposit > _am, "deposit must exceed collect amount");
        require(address(this).balance >= _deposit, "insufficient test balance");

        c.SetMinSum(0);
        c.Initialized();
        c.Put{value: _deposit}(0);

        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;

        bool reverted;
        try c.Collect(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;

        assert(!reverted && afterBal == beforeBal - _am && cBalAfter == cBalBefore - _am);
    }

    receive() external payable {}
}

